#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<long long> left_part, right_part;
    int split_point = n / 2;

    function<void(int, long long)> generate_left = [&](int i, long long total) {
        if (i == split_point) {
            left_part.push_back(total);
        } else {
            generate_left(i + 1, (total + a[i]) % m);
            generate_left(i + 1, total);
        }
    };

    function<void(int, long long)> generate_right = [&](int i, long long total) {
        if (i == n) {
            right_part.push_back(total);
        } else {
            generate_right(i + 1, (total + a[i]) % m);
            generate_right(i + 1, total);
        }
    };

    generate_left(0, 0);
    generate_right(split_point, 0);

    sort(left_part.begin(), left_part.end());

    long long max_sum_value = 0;
    for (auto val : right_part) {
        auto it = lower_bound(left_part.begin(), left_part.end(), m - val);
        if (it != left_part.begin()) {
            long long candidate_sum = *(it - 1) + val;
            if (candidate_sum > max_sum_value) {
                max_sum_value = candidate_sum;
            }
        }
    }

    cout << max_sum_value << "\n";

    return 0;
}
